// Example of restricting access at the gateway level
const routeConfig = {
  '/track': { public: true }, // Accessible to everyone
  '/admin/config': { public: false, role: 'admin' } // Restricted by role
};

function handleRequest(req) {
  const route = routeConfig[req.path];
  if (!route || (!route.public && !req.user.isAdmin)) {
    return { status: 403, message: 'Forbidden' }; // Fail safe: deny by default
  }
  return process(req);
}
